// One Slack message listing the new tenders. No new tender: no message.
const notices = $input.all().map((i) => i.json).filter((n) => n.found !== false);
if (notices.length === 0) return [];
const eur = (v) => (v == null ? 'value n/a' : `€${Math.round(v).toLocaleString('en-US')}`);
const lines = notices.slice(0, 30).map((n) => `• <${n.noticeUrl}|${(n.title ?? '').replace(/[<>|]/g, ' ').slice(0, 150)}>\n   ${n.buyerName ?? 'buyer n/a'} (${n.buyerCountry ?? '?'}), ${eur(n.valueEur)}, deadline ${n.submissionDeadline ? n.submissionDeadline.slice(0, 10) : 'n/a'}`);
if (notices.length > 30) lines.push(`…and ${notices.length - 30} more`);
return [{ json: { text: `:classical_building: *${notices.length} new public tender${notices.length > 1 ? 's' : ''}*\n\n${lines.join('\n')}`, newNotices: notices.length } }];
